def dehydrate_time(value):
    """ Dehydrator for `time` values.

    :param value:
    :type value: Time
    :return:
    """
    if value is None:
        return None

    # Import here to avoid a hard dependency at module level.
    import datetime

    # Handle standard datetime.time objects.
    if isinstance(value, datetime.time):
        return value.isoformat()

    # Handle objects that provide an isoformat method (e.g., datetime.datetime).
    if hasattr(value, "isoformat") and callable(value.isoformat):
        try:
            return value.isoformat()
        except Exception:
            pass

    # Handle custom Time objects that expose their raw string representation via a 'value' attribute.
    if hasattr(value, "value") and isinstance(value.value, str):
        return value.value

    # If none of the above, raise an informative error.
    raise TypeError(
        f"dehydrate_time expects a Time instance or object with an isoformat() method; received type {type(value).__name__}"
    )<|return|>

def dehydrate_point(value):
    """ Dehydrator for Point data.

    :param value:
    :type value: Point
    :return: A serialisable representation of the point or None if value is None
    """
    # Allow None to be passed safely
    if value is None:
        return None

    try:
        # If value is already a Point-like object with attributes x and y
        if hasattr(value, "x") and hasattr(value, "y"):
            x = float(value.x)
            y = float(value.y)
            return {"x": x, "y": y}

        # If value is a tuple/list/iterable of two numeric coordinates
        if isinstance(value, (tuple, list)):
            if len(value) == 2:
                x = float(value[0])
                y = float(value[1])
                return {"x": x, "y": y}

        # If value is a dict with keys 'x' and 'y'
        if isinstance(value, dict):
            if "x" in value and "y" in value:
                x = float(value["x"])
                y = float(value["y"])
                return {"x": x, "y": y}

    except Exception as exc:
        raise ValueError(f"Invalid point data: {value}") from exc

    raise TypeError(f"Unsupported type for point dehydration: {type(value).__name__}")<|return|>

def keys(self):
    """ Return the keys of the record.

    :return: list of key names
    """
    # Prefer an explicit internal mapping if it exists
    data = None
    for attr in ('_data', 'data', 'record'):
        try:
            data = getattr(self, attr)
            if isinstance(data, dict):
                return list(data.keys())
        except Exception:
            continue
    # Fallback: use the instance __dict__
    try:
        return list(self.__dict__.keys())
    except Exception:
        # If we can't access __dict__, return empty list
        return []<|return|>

def index(self, key):
    """ Return the index of the given item.

    :param key: a key
    :return: index
    :rtype: int
    """
    # Determine the underlying sequence to search
    if hasattr(self, "data") and isinstance(self.data, (list, tuple)):
        seq = self.data
    elif hasattr(self, "items") and isinstance(self.items, (list, tuple)):
        seq = self.items
    else:
        try:
            seq = list(self)
        except TypeError:
            raise TypeError("Object is not iterable and has no suitable 'data' or 'items' attribute")

    try:
        return seq.index(key)
    except ValueError:
        raise ValueError(f"'{key}' is not present in the container") from None<|return|>

def values(self, *keys):
    """ Return the values of the record, optionally filtering to
    include only certain values by index or key.

    :param keys: indexes or keys of the items to include; if none
                 are provided, all values will be included
    :return: list of values
    :rtype: list
    """
    # Build a list of (key, value) pairs from the object.
    try:
        # Most records will expose a mapping interface.
        items = list(self.items())
    except AttributeError:
        # Fallback: iterate directly over self assuming it yields pairs.
        items = []
        for item in self:
            if isinstance(item, (list, tuple)) and len(item) == 2:
                items.append((item[0], item[1]))
            else:
                raise TypeError(
                    "Expected the record to be iterable of (key, value) pairs"
                )

    # If no filtering keys are supplied, return all values in order.
    if not keys:
        return [v for _, v in items]

    result = []
    for key in keys:
        if isinstance(key, int):
            # Treat as an index into the items list.
            if 0 <= key < len(items):
                result.append(items[key][1])
            else:
                # Omit out-of-range indices silently to preserve len(items) semantics.
                continue
        else:
            # Treat as a key lookup.
            # Find the first occurrence of this key in the items list.
            for k, v in items:
                if k == key:
                    result.append(v)
                    break
            else:
                # Key not found; ignore silently.
                continue
    return result<|return|>

def data(self, *keys):
    """ Return the keys and values of this record as a dictionary,
    optionally including only certain values by index or key. Keys
    provided in the items that are not in the record will be
    inserted with a value of :const:`None`; indexes provided
    that are out of bounds will trigger an :exc:`IndexError`.

    :param keys: indexes or keys of the items to include; if none
                  are provided, all values will be included
    :return: dictionary of values, keyed by field name
    :raises: :exc:`IndexError` if an out-of-bounds index is specified
    """
    # Retrieve the underlying container that holds the record data.
    container = getattr(self, "_data", None)
    if container is None:
        raise AttributeError(
            f"'{type(self).__name__}' objects have no internal '_data' attribute"
        )

    # If the container is a mapping, simply slice/lookup keys.
    if isinstance(container, dict):
        if not keys:
            return dict(container)
        return {k: container.get(k, None) for k in keys}

    # If the container is a sequence, assume each element is a (key, value) tuple.
    if isinstance(container, (list, tuple)):
        items = list(container)
        key_to_value = {k: v for k, v in items}

        result = {}
        for key in keys:
            if isinstance(key, int):
                try:
                    k, v = items[key]
                except IndexError:
                    raise IndexError(f"Index {key} out of bounds")
                result[k] = v
            else:
                result[key] = key_to_value.get(key, None)
        return result

    # For any other type, raise an error to signal misuse.
    raise TypeError(
        f"Unsupported data container type: {type(container).__name__}"
    )<|return|>

def pop_u16(self):
    """ Remove the last two bytes of data, returning them as a big-endian
    16-bit unsigned integer.
    """
    # Ensure there is enough data to pop
    if not hasattr(self, "data") or self.data is None:
        raise AttributeError("Instance has no 'data' attribute to pop from")
    # Convert to a bytes-like object if necessary
    if isinstance(self.data, bytearray):
        data = self.data
    else:
        data = bytes(self.data)
    if len(data) < 2:
        raise ValueError("Not enough bytes to pop a 16‑bit value")
    # Extract the last two bytes
    value = int.from_bytes(data[-2:], byteorder='big')
    # Remove them from the underlying data
    if isinstance(self.data, bytearray):
        del self.data[-2:]
    else:
        # Reassign a new bytes object
        self.data = data[:-2]
    return value<|return|>

def begin(self, mode=None, bookmarks=None, metadata=None, timeout=None,
          db=None, imp_user=None, dehydration_hooks=None,
          hydration_hooks=None, **handlers):
    """
    Appends a BEGIN message to the output queue.

    :param mode: access mode for routing - "READ" or "WRITE" (default)
    :param bookmarks: iterable of bookmark values after which this transaction should begin
    :param metadata: custom metadata dictionary to attach to the transaction
    :param timeout: timeout for transaction execution (seconds)
    :param db: name of the database against which to begin the transaction
        Requires Bolt 4.0+.
    :param imp_user: the user to impersonate
        Requires Bolt 4.4+
    :param dehydration_hooks:
        Hooks to dehydrate types (dict from type (class) to dehydration
        function). Dehydration functions receive the value and returns an
        object of type understood by packstream.
    :param hydration_hooks:
        Hooks to hydrate types (mapping from type (class) to
        dehydration function). Dehydration functions receive the value of
        type understood by packstream and are free to return anything.
    :param handlers: handler functions passed into the returned Response object
    :return: Response object
    """
    # Validate and normalise mode
    if mode is None:
        mode = "WRITE"
    if not isinstance(mode, str):
        raise TypeError("mode must be a string")
    mode_upper = mode.upper()
    if mode_upper not in ("READ", "WRITE"):
        raise ValueError("mode must be 'READ' or 'WRITE'")
    # Validate bookmarks
    if bookmarks is not None:
        if isinstance(bookmarks, str):
            # Allow a single bookmark string
            bookmarks = [bookmarks]
        try:
            bookmarks_iter = list(bookmarks)
        except Exception as exc:
            raise ValueError("bookmarks must be iterable") from exc
    # Validate metadata
    if metadata is not None and not isinstance(metadata, dict):
        raise TypeError("metadata must be a dict")
    # Validate timeout
    if timeout is not None:
        if not isinstance(timeout, (int, float)):
            raise TypeError("timeout must be a number")
        if timeout <= 0:
            raise ValueError("timeout must be positive")
    # Validate database and impersonated user
    if db is not None and not isinstance(db, str):
        raise TypeError("db must be a string")
    if imp_user is not None and not isinstance(imp_user, str):
        raise TypeError("imp_user must be a string")
    # Validate hooks
    if dehydration_hooks is not None and not isinstance(dehydration_hooks, dict):
        raise TypeError("dehydration_hooks must be a dict")
    if hydration_hooks is not None and not isinstance(hydration_hooks, dict):
        raise TypeError("hydration_hooks must be a dict")
    # Build the BEGIN message
    message = {"type": "BEGIN", "mode": mode_upper}
    if bookmarks is not None:
        message["bookmarks"] = bookmarks_iter
    if metadata:
        message["metadata"] = metadata
    if timeout is not None:
        message["timeout"] = timeout
    if db is not None:
        message["db"] = db
    if imp_user is not None:
        message["imp_user"] = imp_user
    if dehydration_hooks:
        message["dehydration_hooks"] = dehydration_hooks
    if hydration_hooks:
        message["hydration_hooks"] = hydration_hooks
    # Append to the output queue
    try:
        self._out_queue.append(message)
    except AttributeError as exc:
        raise RuntimeError("The wrapped session does not have an output queue") from exc
    # Return a Response instance with the provided handlers
    try:
        return Response(self, **handlers)
    except Exception as exc:
        raise RuntimeError("Failed to create Response object") from exc<|return|>

def deprecated(message):
    """ Decorator for deprecating functions and methods.

    ::

        @deprecated("'foo' has been deprecated in favour of 'bar'")
        def foo(x):
            pass

    """
    def decorator(func):
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            warnings.warn(f"{func.__name__} is deprecated: {message}",
                          DeprecationWarning,
                          stacklevel=2)
            return func(*args, **kwargs)
        return wrapper
    return decorator<|return|>

def parse_version(s: str) -> tuple[int, ...]:
    """poor man's version comparison"""
    if not isinstance(s, str):
        raise TypeError(f"Expected a string, got {type(s).__name__}")
    import re
    parts = re.findall(r'\d+', s.strip())
    if not parts:
        raise ValueError(f"Invalid version string: {s!r}")
    return tuple(int(p) for p in parts)<|return|>

def cached(cache, key=None, lock=None):
    """Decorator to wrap a function with a memoizing callable that saves
    results in a cache.

    Parameters
    ----------
    cache : dict-like
        The cache object used to store results.
    key : callable, optional
        Function that computes the cache key from (args, kwargs).  If ``None``
        a default key based on hashing the arguments tuple and a sorted tuple
        of keyword items is used.  The callable must accept two arguments
        (``args`` and ``kwargs``) and return a hashable value.
    lock : context manager or lock object, optional
        Optional synchronization primitive used when reading from or writing
        to the cache.  It must support either ``__enter__`` / ``__exit__`` or
        ``acquire`` / ``release`` methods.

    Returns
    -------
    decorator : callable
        Function decorator that adds memoization.
    """

    # Define a safe default key function if none is given
    if key is None:
        def default_key(args, kwargs):
            try:
                return hash((tuple(args), tuple(sorted(kwargs.items()))))
            except Exception:
                # If any argument is not hashable, fall back to id-based key
                return (id(args), id(kwargs))
        key_func = default_key
    else:
        key_func = key

    def decorator(func):
        def wrapper(*args, **kwargs):
            # Compute cache key
            try:
                k = key_func(args, kwargs)
            except Exception as exc:
                raise RuntimeError("key function raised an exception") from exc

            # Helper to read cache
            def get_from_cache():
                if hasattr(cache, 'get'):
                    return cache.get(k)
                try:
                    return cache[k]
                except KeyError:
                    return None

            # Helper to write cache
            def set_in_cache(val):
                cache[k] = val

            # Access cache with optional lock
            if lock is not None:
                if hasattr(lock, '__enter__'):
                    with lock:
                        val = get_from_cache()
                        if val is not None:
                            return val
                        val = func(*args, **kwargs)
                        set_in_cache(val)
                        return val
                elif hasattr(lock, 'acquire'):
                    lock.acquire()
                    try:
                        val = get_from_cache()
                        if val is not None:
                            return val
                        val = func(*args, **kwargs)
                        set_in_cache(val)
                        return val
                    finally:
                        lock.release()
                else:
                    raise TypeError("lock must be a context manager or provide acquire()/release()")
            else:
                val = get_from_cache()
                if val is not None:
                    return val
                val = func(*args, **kwargs)
                set_in_cache(val)
                return val

        wrapper.__name__ = func.__name__
        wrapper.__doc__ = func.__doc__
        return wrapper

    return decorator<|return|>

def mru_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Most Recently Used (MRU)
    algorithm.
    """
    # Validate arguments
    if not isinstance(maxsize, int):
        raise TypeError('maxsize must be an integer')
    if maxsize < 0:
        raise ValueError('maxsize must be >= 0')
    if not isinstance(typed, bool):
        raise TypeError('typed must be a bool')

    # Import here to avoid module-level imports
    from collections import OrderedDict
    from functools import wraps

    def decorating_function(user_function):
        cache = {}
        order = OrderedDict()  # keeps insertion order, oldest first

        @wraps(user_function)
        def wrapper(*args, **kwargs):
            # Build key respecting 'typed' option
            if typed:
                key = (args,
                       frozenset(kwargs.items()),
                       tuple(type(v) for v in args),
                       tuple(type(v) for v in kwargs.values()))
            else:
                key = (args, frozenset(kwargs.items()))

            # Handle zero-size cache (no caching)
            if maxsize == 0:
                return user_function(*args, **kwargs)

            if key in cache:
                # Move to the end to mark as recently used
                order.move_to_end(key)
                return cache[key]

            # Compute the function result
            result = user_function(*args, **kwargs)
            cache[key] = result
            order[key] = None

            # Evict oldest entries if cache is over budget
            if len(order) > maxsize:
                oldest_key, _ = order.popitem(last=False)
                del cache[oldest_key]
            return result

        # Expose a simple cache_info for introspection
        wrapper.cache_info = lambda: {
            "hits": 0,  # No hit count semantics implemented
            "misses": 0,
            "maxsize": maxsize,
            "currsize": len(order)
        }

        return wrapper

    return decorating_function<|return|>

def popitem(self):
    """Remove and return the `(key, value)` pair first inserted."""
    return super().popitem(last=False)<|return|>

def cachedmethod(cache, key=hashkey, lock=None):
    """Decorator to wrap a class or instance method with a memoizing
    callable that saves results in a cache.
    """
    def decorator(fn):
        if cache is None:
            # No caching, just return the original function
            return fn

        def wrapper(*args, **kwargs):
            # Determine the key for caching
            try:
                k = key(*args, **kwargs)
            except Exception as exc:
                raise ValueError(
                    f"Cache key function raised an exception: {exc}"
                ) from exc

            # Thread‑safe access if a lock is provided
            if lock:
                lock.acquire()
            try:
                # Return cached result if it exists
                if k in cache:
                    return cache[k]
                # Compute, store, and return the result
                result = fn(*args, **kwargs)
                cache[k] = result
                return result
            finally:
                if lock:
                    lock.release()

        # Preserve basic metadata of the original function
        wrapper.__name__ = fn.__name__
        wrapper.__doc__ = fn.__doc__
        wrapper.__dict__.update(fn.__dict__)
        return wrapper

    return decorator<|return|>

