def directlyProvidedBy(object):  # pylint:disable=redefined-builtin
    """Return the interfaces directly provided by the given object

    The value returned is an `~zope.interface.interfaces.IDeclaration`.
    """
    if object is None:
        raise TypeError("directlyProvidedBy requires a non-None object")

    # Attempt to access the object's own __provides__ attribute
    try:
        return object.__provides__
    except AttributeError:
        pass

    # Fallback: look for the __provides__ on the object's class
    try:
        cls = object if isinstance(object, type) else type(object)
    except Exception as exc:
        raise TypeError("Unable to determine type of object") from exc

    try:
        return cls.__provides__
    except AttributeError:
        pass

    raise ValueError(f"Object {object!r} does not provide any interfaces")<|return|>

def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""
    # Validate input
    if classes is None:
        raise TypeError("classes must be an iterable of class objects, got None")
    try:
        iter(classes)
    except TypeError:
        raise TypeError(f"Expected an iterable of classes, got {type(classes).__name__}")
    # Ensure elements are types
    for idx, cls in enumerate(classes):
        if not isinstance(cls, type):
            raise TypeError(f"Element at index {idx} is not a class: {cls!r}")

    # Build minimal list: keep only classes that are not a subclass of any other
    seen = set()
    result = []
    for cls in classes:
        if cls in seen:
            # Skip duplicate
            continue
        if any(issubclass(cls, other) and other != cls for other in classes):
            continue  # cls is redundant
        result.append(cls)
        seen.add(cls)
    return result
<|return|>

def namesAndDescriptions(self, all=False):  # pylint:disable=redefined-builtin
    """Return attribute names and descriptions defined by interface."""
    # Attempt to retrieve an interface definition from the class.
    interface = getattr(self.__class__, 'INTERFACE', None)
    if interface is None:
        interface = getattr(self.__class__, 'interface', None)

    # If no explicit interface is found, fall back to introspecting
    # class attributes that have a docstring.
    if interface is None:
        interface = {}
        for name in dir(self.__class__):
            if name.startswith('_'):
                continue
            value = getattr(self.__class__, name, None)
            if callable(value):
                continue
            # Use the first line of the docstring as the description if available.
            doc = getattr(value, "__doc__", None)
            if isinstance(doc, str):
                description = doc.strip().splitlines()[0]
                interface[name] = description

    # If still nothing was found, raise an informative error.
    if not interface:
        raise AttributeError(
            f"No interface defined for class {self.__class__.__name__}"
        )

    # Normalise the interface to a list of (name, description) tuples.
    if isinstance(interface, dict):
        items = list(interface.items())
    elif isinstance(interface, (list, tuple)):
        items = list(interface)
    else:
        raise TypeError(
            f"Unsupported interface type {type(interface).__name__} for "
            f"class {self.__class__.__name__}"
        )

    # If 'all' is False, filter out private or internal names.
    if not all:
        items = [(name, desc) for name, desc in items if not name.startswith("_")]

    return items
<|return|>

def _normalizeargs(sequence, output=None):
    """
    Normalize declaration arguments

    Normalization arguments might contain Declarions, tuples, or single
    interfaces.

    Anything but individial interfaces or implements specs will be expanded.
    """
    if output is None:
        output = []
    for arg in sequence:
        if arg is None:
            continue
        # Expand tuples (or any iterable of interfaces) into their elements
        if isinstance(arg, (tuple, list)):
            output.extend(arg)
        # Treat objects that look like declarations (having an .interfaces attribute)
        elif hasattr(arg, "interfaces") and isinstance(arg.interfaces, (list, tuple)):
            output.extend(arg.interfaces)
        # For implements specs or individual interfaces we keep them as is
        else:
            output.append(arg)
    return output<|return|>

def _c_optimizations_required():
    """
    Return a true value if the C optimizations are required.

    This uses the ``PURE_PYTHON`` variable as documented in `_use_c_impl`.
    """
    try:
        # If PURE_PYTHON is truthy, we should *not* use C extensions.
        return not bool(PURE_PYTHON)
    except NameError:
        # If the flag is not defined, assume the C optimizations are needed.
        return True<|return|>

def _get_err_indices(self, coord_name):
    """Get error indices corresponding to a coordinate."""
    # Validate input
    if not isinstance(coord_name, str):
        raise ValueError(f"coord_name must be a string, got {type(coord_name).__name__}")

    # Attempt to retrieve the internal error indices mapping
    try:
        err_map = getattr(self, "_error_indices", {})
    except Exception:
        # In case the attribute lookup itself fails, return empty list
        return []

    # If the mapping is not a dict or hashable, treat as no data
    if not isinstance(err_map, dict):
        return []

    # Attempt to fetch indices for the specified coordinate
    try:
        raw = err_map.get(coord_name)
    except Exception:
        return []

    # If no data found, return empty list
    if raw is None:
        return []

    # Normalize the result to a list of indices
    if isinstance(raw, (list, tuple, set)):
        return list(raw)
    # If a single index is provided (e.g., int), wrap it in a list
    try:
        int(raw)  # ensures it's something index-like
        return [raw]
    except Exception:
        # Unexpected type; return empty list to avoid raising
        return []
<|return|>

def integral(bins, edges):
    """Compute integral (scale for a histogram).

    *bins* contain values, and *edges* form the mesh
    for the integration.
    Their format is defined in :class:`.histogram` description.
    """
    # Ensure inputs are iterable
    try:
        bins_list = list(bins)
        edges_list = list(edges)
    except TypeError:
        raise TypeError("bins and edges must be iterable")

    if len(edges_list) != len(bins_list) + 1:
        raise ValueError("Number of edges must be one more than number of bins")

    # Compute widths and validate edges
    widths = []
    for i in range(len(bins_list)):
        try:
            low = float(edges_list[i])
            high = float(edges_list[i + 1])
        except Exception as e:
            raise TypeError("All edge values must be convertible to float") from e

        width = high - low
        if width <= 0:
            raise ValueError("Edges must increase monotonically (strictly)")
        widths.append(width)

    # Compute integral
    total = 0.0
    for bin_val, width in zip(bins_list, widths):
        try:
            val = float(bin_val)
        except Exception as e:
            raise TypeError("All bin values must be convertible to float") from e
        total += val * width

    return total<|return|>

def is_fill_request_seq(seq):
    """Test whether *seq* can be converted to a FillRequestSeq.

    True only if it is a FillRequest element
    or contains at least one such,
    and it is not a Source sequence.
    """
    try:
        # If seq is a single element that is a FillRequest
        if isinstance(seq, FillRequest):
            return True

        # Reject if seq itself is a Source or SourceSeq (i.e., a source sequence)
        if isinstance(seq, (Source, SourceSeq)):
            return False

        # If seq is an iterable (but not a string/bytes)
        if hasattr(seq, '__iter__') and not isinstance(seq, (str, bytes)):
            contains_fill = False
            for el in seq:
                # If any element is a source, the sequence is not valid
                if isinstance(el, Source):
                    return False
                # Mark if a FillRequest is found
                if isinstance(el, FillRequest):
                    contains_fill = True
            return contains_fill

        # If none of the above, not a valid fill request sequence
        return False
    except Exception:
        # In case any of the type checks fail (e.g., classes not defined)
        return False<|return|>

def is_fill_request_el(obj):
    """Object contains executable methods 'fill' and 'request'."""
    try:
        has_fill = hasattr(obj, 'fill') and callable(getattr(obj, 'fill'))
        has_request = hasattr(obj, 'request') and callable(getattr(obj, 'request'))
        return has_fill and has_request
    except Exception:
        # If any error occurs during attribute access, treat as not a fill/request element
        return False<|return|>

