def difference(d1, d2, level=-1):
    """Return a dictionary with items from *d1* not contained in *d2*.

    *level* sets the maximum depth of recursion. For infinite recursion,
    set that to -1. For level 1,
    if a key is present both in *d1* and *d2* but has different values,
    it is included into the difference.
    See :func:`intersection` for more details.

    *d1* and *d2* remain unchanged. However, *d1* or some of its
    subdictionaries may be returned directly.
    Make a deep copy of the result when appropriate.

    .. versionadded:: 0.5
       add keyword argument *level*.
    """
    # Validate input types
    if not isinstance(d1, dict) or not isinstance(d2, dict):
        raise TypeError("Both d1 and d2 must be dictionaries")

    # Normalize level: only -1 (infinite) and positive integers are allowed
    if level < -1:
        raise ValueError("level must be -1 (infinite) or non-negative integer")
    if level == 0:
        # No recursion allowed; simply compare top-level keys
        return {k: v for k, v in d1.items() if k not in d2}

    result = {}
    for key, val1 in d1.items():
        if key not in d2:
            # Key missing in d2 – include the whole entry
            result[key] = val1
            continue

        val2 = d2[key]
        # Both values are dictionaries – recurse if allowed
        if isinstance(val1, dict) and isinstance(val2, dict):
            # Determine the next recursion depth
            next_level = level - 1 if level > 0 else level
            if next_level != 0:
                subdiff = difference(val1, val2, next_level)
                if subdiff:
                    result[key] = subdiff
            # If next_level == 0, no recursion – skip
        else:
            # For non-dict values, include if they differ
            if val1 != val2:
                result[key] = val1

    return result<|return|>

def fill(self, coord, weight=1):
    """Fill histogram at *coord* with the given *weight*.

    Coordinates outside the histogram edges are ignored.
    """
    # Import numpy lazily (assume numpy is available in the class context)
    try:
        import numpy as np
    except ImportError:
        raise ImportError("numpy is required for histogram filling")

    # Validate weight
    try:
        w = float(weight)
    except Exception:
        raise ValueError("`weight` must be a numeric value")

    # Validate coordinate
    if coord is None or isinstance(coord, (str, bytes)):
        raise ValueError("`coord` must be an iterable of numeric coordinates")
    # Convert to list for length checks
    coord = list(coord)
    if not hasattr(self, "edges") or not isinstance(self.edges, (list, tuple)):
        raise AttributeError("Histogram object must have `edges` attribute")
    if len(coord) != len(self.edges):
        raise ValueError("Coordinate dimensionality does not match histogram dimensionality")

    indices = []
    for c, edges in zip(coord, self.edges):
        # Ensure edges array is sorted
        edges_arr = np.asarray(edges)
        if edges_arr.ndim != 1:
            raise ValueError("Histogram edges should be 1D arrays")
        # Find bin index
        idx = np.searchsorted(edges_arr, c, side="right") - 1
        # If outside the range, ignore this point
        if idx < 0 or idx >= len(edges_arr) - 1:
            return
        indices.append(idx)

    # Increment the histogram bin
    try:
        self._data[tuple(indices)] += w
    except AttributeError:
        raise AttributeError("Histogram object must have `_data` numpy array to accumulate counts")
    except Exception as exc:
        raise RuntimeError(f"Failed to increment histogram bin: {exc}")<|return|>

