        # Dynamically import modules to avoid top-level imports
        os = __import__("os")
        json = __import__("json")

        # If path is a pyfilesystem2 FileSystem root
        if hasattr(path, "exists") and hasattr(path, "isdir"):
            if not path.isdir("."):
                return False
            if not path.isdir("objects"):
                return False
            if path.isfile("manifest.json"):
                try:
                    with path.open("manifest.json", "r") as f:
                        json.load(f)
                except Exception:
                    return False
        else:
            # Treat path as a file system path (string, Path-like, etc.)
            root = os.path.abspath(path)
            if not os.path.isdir(root):
                return False
            if not os.path.isdir(os.path.join(root, "objects")):
                return False
            manifest = os.path.join(root, "manifest.json")
            if os.path.isfile(manifest):
