def status_str(self, prefix=''):
        """Return string of validator status, with optional prefix."""
        # Validate prefix type
        if not isinstance(prefix, str):
            raise ValueError("prefix must be a string")
        status = None
        try:
            # Try to get status from a validator attribute if present
            validator = getattr(self, 'validator', None)
            if validator is not None:
                # Prefer direct attribute, fall back to method
                status = getattr(validator, 'status', None)
                if status is None and hasattr(validator, 'get_status'):
                    status = validator.get_status()
            # If no validator or no status from it, check alternative attributes
            if status is None:
                for attr_name in ('validator_status', 'validation_status', 'status'):
                    status = getattr(self, attr_name, None)
                    if status is not None:
                        break
            # If still none, default to empty string
            if status is None:
                status = ''
        except Exception:
            # In case of any unexpected error, fall back to empty status
            status = ''
        return f"{prefix}{str(status)}"<|return|>

def status_str(self, prefix=''):
    """Return string representation of validation log, with optional prefix."""
    try:
        prefix_str = str(prefix)
    except Exception:
        prefix_str = ''
    # Retrieve the log; it may be named 'validation_log' or 'log'
    log = getattr(self, 'validation_log', None)
    if log is None:
        log = getattr(self, 'log', None)
    if not log:
        return ''
    try:
        iter(log)
    except TypeError:
        # Log is not iterable, convert to string
        return prefix_str + str(log)
    lines = []
    for entry in log:
        if isinstance(entry, tuple):
            # Assume (level, message)
            level, msg = entry
            lines.append(f"{prefix_str}{level}: {msg}")
        else:
            lines.append(f"{prefix_str}{entry}")
    return '\n'.join(lines)<|return|>

def validate(self, inventory, extract_spec_version=False):
    """Validate a given inventory.

    If extract_spec_version is True then will look at the type value to determine
    the specification version. In the case that there is no type value or it isn't
    valid, then other tests will be based on the version given in self.spec_version.
    """
    # Basic sanity check
    if not isinstance(inventory, dict):
        raise TypeError("inventory must be a dictionary")

    # Known specification versions
    KNOWN_VERSIONS = {"1.0", "1.1", "2.0"}

    # Helper to compare version strings numerically
    def _compare(v1, v2):
        try:
            parts1 = [int(p) for p in v1.split(".")]
            parts2 = [int(p) for p in v2.split(".")]
        except Exception:
            return 0
        # Pad with zeros for equal length comparison
        length = max(len(parts1), len(parts2))
        parts1 += [0] * (length - len(parts1))
        parts2 += [0] * (length - len(parts2))
        if parts1 == parts2:
            return 0
        return -1 if parts1 < parts2 else 1

    # Extract and set spec_version if requested
    if extract_spec_version:
        type_val = inventory.get("type")
        if type_val in KNOWN_VERSIONS:
            self.spec_version = type_val
        else:
            # fall back to any explicit spec_version in inventory
            spec_val = inventory.get("spec_version")
            if spec_val in KNOWN_VERSIONS:
                self.spec_version = spec_val
            else:
                # keep current self.spec_version if present, else default
                if not hasattr(self, "spec_version"):
                    self.spec_version = "1.0"

    # Ensure elements key exists
    if "elements" not in inventory:
        raise ValueError("inventory must contain an 'elements' key")
    elements = inventory["elements"]
    if not isinstance(elements, list):
        raise ValueError("'elements' must be a list")

    # Validate each element
    for idx, el in enumerate(elements):
        if not isinstance(el, dict):
            raise ValueError(f"element at index {idx} is not a dict")
        if "id" not in el:
            raise ValueError(f"element at index {idx} missing required 'id' key")
        if not isinstance(el["id"], (str, int)):
            raise ValueError(f"element at index {idx} has invalid 'id' type: {type(el['id']).__name__}")

        # For spec_version >= 2.0, require 'content' field
        if hasattr(self, "spec_version") and _compare(self.spec_version, "2.0") >= 0:
            if "content" not in el:
                raise ValueError(f"element at index {idx} missing required 'content' key for spec_version {self.spec_version}")

    # If all checks passed
    return True
<|return|>

def check_digests_present_and_used(self, manifest_files, digests_used):
    """Check all digests in manifest that are needed are present and used."""
    if not isinstance(manifest_files, dict):
        raise TypeError("manifest_files must be a dict mapping digests to file names.")
    # Normalize digests to sets
    manifest_digests = set(manifest_files.keys())
    if digests_used is None:
        digests_used = set()
    else:
        try:
            digests_used = set(digests_used)
        except TypeError as exc:
            raise TypeError("digests_used must be an iterable of digest values.") from exc
    # Determine missing and unused digests
    missing = digests_used - manifest_digests
    unused  = manifest_digests - digests_used
    # Build error message, if any
    if missing or unused:
        msgs = []
        if missing:
            msgs.append(f"Missing digests in manifest: {', '.join(sorted(missing))}")
        if unused:
            msgs.append(f"Unused digests in manifest: {', '.join(sorted(unused))}")
        raise ValueError("; ".join(msgs))<|call|>

def validate_as_prior_version(self, prior):
        """Check that prior is a valid prior version of the current inventory object.

        The input variable prior is also expected to be an InventoryValidator object
        and both self and prior inventories are assumed to have been checked for
        internal consistency.
        """
        # Ensure the prior argument is the correct type
        if not isinstance(prior, InventoryValidator):
            raise TypeError("prior must be an InventoryValidator instance")

        # Retrieve the underlying inventory objects safely
        try:
            self_inv = self.inventory
            prior_inv = prior.inventory
        except AttributeError as exc:
            raise AttributeError("Both the current instance and the prior "
                                 "must expose an 'inventory' attribute.") from exc

        # Compare identifiers – they must match for a valid prior version
        if hasattr(self_inv, "id") and hasattr(prior_inv, "id"):
            if self_inv.id != prior_inv.id:
                raise ValueError("Cannot compare inventories with different IDs: "
                                 f"current={self_inv.id!r}, prior={prior_inv.id!r}")

        # Validate that the prior inventory is indeed older (strictly less version)
        if not hasattr(self_inv, "version") or not hasattr(prior_inv, "version"):
            raise AttributeError("Both inventories must expose a 'version' attribute.")

        if prior_inv.version >= self_inv.version:
            raise ValueError(f"The prior inventory version ({prior_inv.version}) is "
                             f"not older than the current inventory version ({self_inv.version}).")

        # Basic content checking – every element present in the prior must exist
        # in the current inventory with at least the same data.
        if not hasattr(self_inv, "elements") or not hasattr(prior_inv, "elements"):
            raise AttributeError("Both inventories must expose an 'elements' "
                                 "attribute that is a mapping of element IDs to data.")

        for elem_id, elem_data in prior_inv.elements.items():
            if elem_id not in self_inv.elements:
                raise ValueError(f"Element ID '{elem_id}' is present in the prior "
                                 "inventory but missing in the current inventory.")

            # If the elements are mappings, ensure the prior data is a subset
            current_data = self_inv.elements[elem_id]
            if isinstance(elem_data, dict) and isinstance(current_data, dict):
                missing_keys = set(elem_data) - set(current_data)
                if missing_keys:
                    raise ValueError(f"Element '{elem_id}' in the prior inventory contains "
                                     f"keys {missing_keys} that are missing in the current inventory.")
            # For non-dict data, a simple equality check may suffice
            else:
                if elem_data != current_data:
                    raise ValueError(f"Data mismatch for element '{elem_id}'. "
                                     "Prior and current inventories contain different data.")

        # If all checks passed, return True indicating a valid prior version
        return True<|return|>

def validate_fixity(self, fixity, manifest_files):
    """Validate fixity block in inventory.

    Check the structure of the fixity block and makes sure that only files
    listed in the manifest are referenced.
    """
    # Basic type checks and normalisation
    if not isinstance(fixity, dict):
        raise ValueError(f"Expected fixity to be a dict, got {type(fixity).__name__}")

    if not isinstance(manifest_files, (set, list, tuple)):
        manifest_files = set(manifest_files)

    errors = []

    # The fixity block must contain a 'files' key with a list value
    if 'files' not in fixity:
        errors.append("Missing 'files' key in fixity block")
    files_list = fixity.get('files', None)
    if files_list is None or not isinstance(files_list, list):
        errors.append("'files' entry must be a list")
    else:
        for idx, entry in enumerate(files_list):
            # Each entry must be a dict
            if not isinstance(entry, dict):
                errors.append(f"Fixity file entry at index {idx} is not a dict")
                continue

            # Must contain a 'name' key
            if 'name' not in entry:
                errors.append(f"File entry at index {idx} missing 'name' key")
                continue

            name = entry['name']
            if not isinstance(name, str):
                errors.append(f"File entry at index {idx} has non-string 'name'")
                continue

            # Ensure the referenced file exists in the manifest
            if name not in manifest_files:
                errors.append(f"File '{name}' referenced in fixity not present in manifest")

            # Optionally validate checksum format if present
            if 'checksum' in entry and not isinstance(entry['checksum'], str):
                errors.append(f"File entry at index {idx} has non-string 'checksum'")

    if errors:
        raise ValueError("Invalid fixity block: " + "; ".join(errors))

    # If no problems, return True
    return True<|return|>

