def _explore_folder(folder):
    """Get packages' data from folder

    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    folder : str
        Folder of the package
    Returns
    -------
    dict
    """
    if not isinstance(folder, str):
        raise TypeError("folder must be a string path")
    if not os.path.isdir(folder):
        raise FileNotFoundError(f"Folder does not exist: {folder}")

    try:
        # Find all XML basenames in the folder
        xml_bases = set()
        for entry in os.listdir(folder):
            path = os.path.join(folder, entry)
            if not os.path.isfile(path):
                continue
            base, ext = os.path.splitext(entry)
            if ext.lower() == ".xml":
                xml_bases.add(base)

        # Group all files that share an XML basename
        data = {}
        for entry in os.listdir(folder):
            path = os.path.join(folder, entry)
            if not os.path.isfile(path):
                continue
            base, _ = os.path.splitext(entry)
            if base in xml_bases:
                data.setdefault(base, []).append(path)

        return data
    except OSError as exc:
        raise RuntimeError(f"Error accessing folder {folder}: {exc}") from exc<|return|>

