def pretty(self, indent=0, debug=False):
        """Return a pretty formatted representation of self."""
        indent_str = '  ' * indent
        # Base representation: element type
        elem_name = self.__class__.__name__
        if debug and hasattr(self, 'id') and getattr(self, 'id'):
            elem_name += f" (id={self.id})"
        result = f"{indent_str}{elem_name}"
        # Optional attribute listing
        attrs = None
        if hasattr(self, 'attributes') and self.attributes:
            attrs = self.attributes
        elif hasattr(self, 'attrib') and self.attrib:
            attrs = self.attrib
        if attrs:
            parts = [f"{k}={v!r}" for k, v in attrs.items()]
            result += " [" + ", ".join(parts) + "]"
        lines = [result]
        # Recursively pretty‑print children
        try:
            children = list(self)
        except TypeError:
            # self is not iterable, treat as leaf
            children = []
        for child in children:
            if hasattr(child, 'pretty') and callable(child.pretty):
                child_str = child.pretty(indent + 1, debug)
                lines.append(child_str)
            else:
                # Simple leaf value
                leaf = f"{'  ' * (indent + 1)}{child!r}"
                lines.append(leaf)
        return "\n".join(lines)<|return|>

def tzname_in_python2(namefunc):
    """Change unicode output into bytestrings in Python 2

    tzname() API changed in Python 3. It used to return bytes, but was changed
    to unicode strings
    """
    import sys
    try:
        _unicode_type = unicode
    except NameError:
        _unicode_type = str

    def _wrapper(*args, **kwargs):
        result = namefunc(*args, **kwargs)
        if sys.version_info[0] == 2 and isinstance(result, _unicode_type):
            try:
                return result.encode("utf-8")
            except (UnicodeEncodeError, AttributeError):
                # Fallback in case encoding fails
                return result.encode("utf-8", "ignore")
        return result

    return _wrapper<|return|>

