    # If pieces is a string, iterate over characters
    if isinstance(pieces, str):
        return '+' if '+' not in pieces else '.'
    # For iterable types (lists, tuples, sets, etc.)
    try:
        return '+' if '+' not in pieces else '.'
    except Exception:
        # Fallback: treat as string representation
        return '+' if '+' not in str(pieces) else '.'<|return|>

def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    """Validate storage root hierarchy.

    Returns:
        num_objects - number of objects checked
        good_objects - number of objects checked that were found to be valid
    """
    # Parameter type checking
    if not isinstance(validate_objects, bool):
        raise TypeError("validate_objects must be a bool")
    if not isinstance(check_digests, bool):
        raise TypeError("check_digests must be a bool")
    if not isinstance(show_warnings, bool):
        raise TypeError("show_warnings must be a bool")

    total = 0
    good = 0

    def _iterate(node):
        """Recursively iterate over the hierarchy starting at node."""
        yield node
        # Many nodes may expose an __iter__ interface to their children
        if hasattr(node, "__iter__"):
            try:
                for child in node:
                    # Avoid infinite recursion if a node mistakenly yields itself
                    if child is not node:
                        yield from _iterate(child)
            except Exception:
                # If the node cannot be iterated, skip its children
                pass

    for obj in _iterate(self):
        total += 1
        is_valid = True
        # Object validation
        if validate_objects:
            try:
                if hasattr(obj, "validate"):
                    is_valid = bool(obj.validate())
                else:
                    # Assume valid if no validate method
                    is_valid = True
            except Exception as exc:
                is_valid = False
                if show_warnings:
                    try:
                        import warnings
                        warnings.warn(f"Validation failed for {obj!r}: {exc}", RuntimeError)
                    except Exception:
                        # Fallback if warnings module cannot be used
                        print(f"WARNING: Validation failed for {obj!r}: {exc}")
        # Digest / checksum check
        digest_ok = True
        if check_digests:
            try:
                if hasattr(obj, "check_digest"):
                    digest_ok = bool(obj.check_digest())
                else:
                    digest_ok = True
            except Exception as exc:
                digest_ok = False
                if show_warnings:
                    try:
                        import warnings
                        warnings.warn(f"Digest check failed for {obj!r}: {exc}", RuntimeError)
                    except Exception:
                        print(f"WARNING: Digest check failed for {obj!r}: {exc}")
        if is_valid and digest_ok:
            good += 1

    return total, good<|return|>

