def parse_subparser_arguments(unparsed_arguments, subparsers):
    '''
    Given a sequence of arguments and a dict from subparser name to argparse.ArgumentParser
    instance, give each requested action's subparser a shot at parsing all arguments. This allows
    common arguments like "--repository" to be shared across multiple subparsers.

    Return the result as a tuple of (a dict mapping from subparser name to a parsed namespace of
    arguments, a list of remaining arguments not claimed by any subparser).
    '''
    parsed = {}
    unknown_by_parser = {}

    # Parse each subparser against the full argument list
    for name, parser in subparsers.items():
        try:
            args, unknown = parser.parse_known_args(unparsed_arguments)
        except Exception:
            # If parsing fails, fall back to an empty namespace and keep all args unknown
            try:
                args = parser.parse_args([])
            except Exception:
                args = type('Namespace', (), {})()
            unknown = list(unparsed_arguments)
        parsed[name] = args
        unknown_by_parser[name] = unknown

    # Compute arguments that none of the parsers recognised
    if unknown_by_parser:
        # Convert each unknown list to a set for fast lookup
        unknown_sets = [set(unknown) for unknown in unknown_by_parser.values()]
        remaining = [
            arg
            for arg in unparsed_arguments
            if all(arg in s for s in unknown_sets)
        ]
    else:
        remaining = list(unparsed_arguments)

    return parsed, remaining<|return|>

def bash_completion():
    """
    Return a bash completion script for the borgmatic command. Produce this by introspecting
    borgmatic's command-line argument parsers.
    """
    try:
        import borgmatic.main as bm_main
        import argparse
    except Exception as exc:
        return f"# Error generating completion: {exc}\n"

    # Try to obtain an argparse parser object. If the main module exposes it as
    # 'parser', use that; otherwise look for any attribute that is an instance of
    # argparse.ArgumentParser.
    parser = getattr(bm_main, 'parser', None)
    if parser is None:
        for name, obj in vars(bm_main).items():
            if isinstance(obj, argparse.ArgumentParser):
                parser = obj
                break

    if not parser:
        return "# No ArgumentParser found in borgmatic.main. Completion not available.\n"

    # Gather command‑line options derived from the parser.
    opts = []
    for action in parser._actions:
        # Skip actions that are suppressed or don't correspond to a real flag.
        if isinstance(action, argparse._StoreAction):
            if action.option_strings:
                opts.extend(action.option_strings)
            else:
                # Positional arguments are simplified to their destination name.
                opts.append(action.dest)

    opts_str = ' '.join(opts)

    script = f"""
_borgmatic_complete()
{{
    local cur opts
    COMPREPLY=()
    cur="${{COMP_WORDS[COMP_CWORD]}}"
    opts="{opts_str}"
    COMPREPLY=( $(compgen -W "$opts" -- "$cur") )
    return 0
}}
complete -F _borgmatic_complete borgmatic
"""
    return script.strip()
<|return|>

def _dictsum(dicts):
    """
    Combine values of the dictionaries supplied by iterable dicts.

    >>> _dictsum([{'a': 1, 'b': 2}, {'a': 5, 'b': 0}])
    {'a': 6, 'b': 2}
    """
    result = {}
    # Validate input is iterable and contains mappings
    try:
        iterator = iter(dicts)
    except TypeError:
        raise TypeError("Argument 'dicts' must be an iterable of dictionaries.")

    for d in iterator:
        if not isinstance(d, dict):
            raise TypeError(f"Expected dict in dicts, got {type(d).__name__}")
        for k, v in d.items():
            result[k] = result.get(k, 0) + v

    return result<|return|>

def _replace_url_args(url, url_args):
    """Replace any custom string URL items with values in args."""
    # Validate input types
    if url is None:
        return None
    if not isinstance(url, str):
        raise TypeError(f"url must be a string or None, got {type(url).__name__}")
    if url_args is None:
        return url
    if not isinstance(url_args, (dict,)):
        try:
            # attempt to convert to dict if sequence of pairs
            url_args = dict(url_args)
        except Exception as exc:
            raise TypeError(f"url_args must be a mapping or convertible to dict, got {type(url_args).__name__}") from exc

    # Regular expression to find placeholders in the form {key}
    import re
    import urllib.parse
    pattern = re.compile(r'\{(\w+)\}')

    def _replace_match(match):
        key = match.group(1)
        if key not in url_args:
            raise KeyError(f"Missing key '{key}' in url_args for URL replacement")
        # Convert value to string and encode it for URL safety
        value = str(url_args[key])
        return urllib.parse.quote(value, safe='')

    # Perform the substitution
    replaced_url = pattern.sub(_replace_match, url)
    return replaced_url<|return|>

