def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    """Convert a number to a string, using the given alphabet.

    The output has the most significant digit first.
    """
    # Validate inputs
    if not isinstance(number, int):
        raise TypeError(f"number must be an integer, got {type(number).__name__}")
    if number < 0:
        raise ValueError("number must be non‑negative")
    if not alphabet or not isinstance(alphabet, list) or not all(isinstance(c, str) for c in alphabet):
        raise ValueError("alphabet must be a non‑empty list of strings")
    base = len(alphabet)
    if base < 2:
        raise ValueError("alphabet must contain at least two symbols to represent a number base")

    # Handle the zero case
    if number == 0:
        digits = [alphabet[0]]
    else:
        digits = []
        n = number
        while n > 0:
            digits.append(alphabet[n % base])
            n //= base
        digits.reverse()

    # Apply padding if requested
    if padding is not None:
        if not isinstance(padding, int) or padding < 0:
            raise ValueError("padding must be a non‑negative integer or None")
        if len(digits) < padding:
            pad_length = padding - len(digits)
            digits = [alphabet[0]] * pad_length + digits

    return "".join(digits)<|return|>

def _replace_register(flow_params, register_number, register_value):
    """Replace value from flows to given register number

    'register_value' key in dictionary will be replaced by register number
    given by 'register_number'

    :param flow_params: Dictionary containing defined flows
    :param register_number: The number of register where value will be stored
    :param register_value: Key to be replaced by register number

    """
    # Validate parameters
    if register_number is None:
        raise ValueError("register_number must not be None")
    if register_value is None:
        raise ValueError("register_value must not be None")

    def _replace(item):
        try:
            if isinstance(item, dict):
                return {k: _replace(v) if v == register_value else _replace(v) if isinstance(v, (dict, list)) else v
                        for k, v in item.items()}
            elif isinstance(item, list):
                return [_replace(elem) if elem == register_value else _replace(elem) if isinstance(elem, (dict, list)) else elem
                        for elem in item]
            else:
                return register_number if item == register_value else item
        except Exception as exc:
            raise ValueError(f"Error processing item {item!r}: {exc}") from exc

    return _replace(flow_params)<|return|>

