def string_to_int(string: str, alphabet: List[str]) -> int:
    """
    Convert a string to a number, using the given alphabet.

    The input is assumed to have the most significant digit first.
    """
    # Validate alphabet
    if not alphabet:
        raise ValueError("Alphabet must contain at least one symbol.")
    if len(set(alphabet)) != len(alphabet):
        raise ValueError("Alphabet symbols must be unique.")

    base = len(alphabet)
    if base == 1:
        raise ValueError("Alphabet must contain more than one symbol to form a valid base.")

    # Build digit mapping for fast lookup
    digit_map: Dict[str, int] = {ch: idx for idx, ch in enumerate(alphabet)}

    if not string:
        raise ValueError("Input string must not be empty.")

    result = 0
    for pos, ch in enumerate(string):
        if ch not in digit_map:
            raise ValueError(
                f"Invalid character '{ch}' at position {pos}. "
                f"Expected one of {''.join(alphabet)}."
            )
        result = result * base + digit_map[ch]

    return result<|return|>

def get_repo_archive(url: str, destination_path: Path) -> Path:
    """
    Given an url and a destination path, retrieve and extract .tar.gz archive
    which contains 'desc' file for each package.
    Each .tar.gz archive corresponds to an Arch Linux repo ('core', 'extra', 'community').

    Args:
        url: url of the .tar.gz archive to download
        destination_path: the path on disk where to extract archive

    Returns:
        a directory Path where the archive has been extracted to.
    """
    if not isinstance(url, str):
        raise TypeError("url must be a string")
    if not isinstance(destination_path, Path):
        raise TypeError("destination_path must be a pathlib.Path instance")

    # Ensure the destination directory exists
    if destination_path.exists():
        if not destination_path.is_dir():
            raise ValueError(f"destination_path exists and is not a directory: {destination_path}")
    else:
        destination_path.mkdir(parents=True, exist_ok=True)

    # Download the archive
    try:
        with requests.get(url, stream=True, timeout=(10, 10)) as r:
            r.raise_for_status()
            temp_archive = destination_path / "temp_repo.tar.gz"
            with open(temp_archive, "wb") as f:
                for chunk in r.iter_content(chunk_size=8192):
                    if chunk:
                        f.write(chunk)
    except requests.RequestException as e:
        raise RuntimeError(f"Failed to download repository archive from {url}: {e}") from e

    # Extract the archive
    try:
        import tarfile
        with tarfile.open(temp_archive, "r:gz") as tar:
            tar.extractall(path=destination_path)
    except Exception as e:
        if temp_archive.exists():
            try:
                temp_archive.unlink()
            except OSError:
                pass
        raise RuntimeError(f"Failed to extract archive {temp_archive}: {e}") from e

    # Clean up the temporary archive file
    try:
        temp_archive.unlink()
    except OSError:
        pass

    return destination_path<|return|>

