def regex_dict(item):
    """Convert *.cpp keys to regex keys

    Given a dict where the keys are all filenames with wildcards, convert only
    the keys into equivalent regexes and leave the values intact.

    Example:

    rules = {
        '*.cpp':
            {'a': 'arf', 'b': 'bark', 'c': 'coo'},
        '*.h':
            {'h': 'help'}
    }
    regex_keys = regex_dict(rules)

    Args:
        item: dict to convert
    Returns:
        dict with keys converted to regexes
    """
    if not isinstance(item, dict):
        raise TypeError('regex_dict expects a dictionary')

    def _glob_to_regex(pattern):
        # Escape all regex special characters except * and ?
        # then replace * with .* and ? with .
        escaped = []
        for ch in pattern:
            if ch == '*':
                escaped.append('.*')
            elif ch == '?':
                escaped.append('.')
            elif ch in r'.^$+{}[]|()':
                escaped.append('\\' + ch)
            else:
                escaped.append(ch)
        regex = '^' + ''.join(escaped) + '$'
        return regex

    result = {}
    for key, value in item.items():
        if not isinstance(key, str):
            raise TypeError(f'All keys must be strings, got {type(key).__name__}')
        regex_key = _glob_to_regex(key)
        result[regex_key] = value
    return result<|return|>

