def split(s, platform='this'):
    """Multi-platform variant of shlex.split() for command-line splitting.
    For use with subprocess, for argv injection etc. Using fast REGEX.

    platform: 'this' = auto from current platform;
              1 = POSIX;
              0 = Windows/CMD
              (other values reserved)
    """
    import sys, shlex
    if s is None:
        return []

    # Resolve platform parameter
    if platform in ('this', None, True, False):
        platform = 0 if sys.platform.startswith('win') else 1
    elif isinstance(platform, str):
        if platform.strip().lower() in ('posix', '1'):
            platform = 1
        elif platform.strip().lower() in ('win', 'windows', '0'):
            platform = 0
        else:
            platform = 1  # Default to POSIX for unknown strings

    # Perform the split
    if platform == 1:  # POSIX rules
        return shlex.split(s, posix=True)
    elif platform == 0:  # Windows/CMD rules
        return shlex.split(s, posix=False)
    else:
        # Fallback to POSIX if an unrecognized code is supplied
        return shlex.split(s, posix=True)<|return|>

def is_local(host):
    """
    Checks if the host is the localhost

    :param host: The hostname or ip
    :return: True if the host is the localhost
    """
    if not host:
        return False

    # Normalise host by removing any trailing port information
    # If host contains a colon that is not part of IPv6, split on last colon
    # (IPv6 addresses are usually surrounded by square brackets in URLs)
    base_host = host
    if ':' in host and not (host.startswith('[') and host.endswith(']')):
        try:
            # Only split on the last colon (e.g., "127.0.0.1:8080")
            base_host = host.rsplit(':', 1)[0]
        except Exception:
            pass

    # Quick check for common localhost identifiers
    lower = base_host.strip().lower()
    if lower in ('localhost', '127.0.0.1', '::1'):
        return True

    try:
        # Resolve the hostname/IP to addresses
        addrs = socket.getaddrinfo(base_host, None)
    except socket.gaierror:
        return False

    # Check each resolved address
    for result in addrs:
        family, _, _, _, sockaddr = result
        if family == socket.AF_INET:
            ip = sockaddr[0]
            if ip.startswith('127.'):
                return True
        elif family == socket.AF_INET6:
            ip = sockaddr[0]
            if ip == '::1':
                return True
    return False<|return|>

def is_gitbash():
    """
    returns True if you run in a Windows gitbash

    :return: True if gitbash
    """
    try:
        # Only relevant on Windows
        if os.name != 'nt':
            return False

        # Git Bash (MSYS2/Cygwin) typically defines MSYSTEM or OSTYPE
        if 'MSYSTEM' in os.environ:
            return True

        ostype = os.environ.get('OSTYPE', '').lower()
        if ostype.startswith('msys') or ostype.startswith('cygwin'):
            return True

        return False
    except Exception:
        # In case of unexpected errors, be conservative
        return False<|return|>

def write_configuration(config_filename, rendered_config, mode=0o600, overwrite=False):
    '''
    Given a target config filename and rendered config YAML, write it out to file. Create any
    containing directories as needed. But if the file already exists and overwrite is False,
    abort before writing anything.
    '''
    # Validate inputs
    if not isinstance(config_filename, (str, bytes, os.PathLike)):
        raise TypeError('config_filename must be a string or path-like object')
    if not isinstance(rendered_config, str):
        raise TypeError('rendered_config must be a string containing YAML')
    if not isinstance(mode, int):
        raise TypeError('mode must be an integer octal permission flag')
    if not isinstance(overwrite, bool):
        raise TypeError('overwrite must be a boolean')

    # Resolve absolute path and ensure directory exists
    path = os.path.abspath(str(config_filename))
    dir_path = os.path.dirname(path)
    if dir_path and not os.path.exists(dir_path):
        try:
            os.makedirs(dir_path, exist_ok=True)
        except OSError as exc:
            raise OSError(f'Failed to create directories for {path}: {exc}') from exc

    # Abort if file exists and overwrite is False
    if os.path.exists(path) and not overwrite:
        return  # nothing written

    # Write the configuration file
    try:
        with open(path, 'w', encoding='utf-8') as f:
            f.write(rendered_config)
        # Set the file permissions
        os.chmod(path, mode)
    except Exception as exc:
        # Clean up partial file if it was created
        if os.path.exists(path):
            try:
                os.remove(path)
            except Exception:
                pass  # ignore cleanup errors
        raise IOError(f'Failed to write configuration file to {path}: {exc}') from exc<|return|>

def _resolve_string(matcher):
    '''
    Get the value from environment given a matcher containing a name and an optional default value.
    If the variable is not defined in environment and no default value is provided, an Error is raised.
    '''
    # Extract variable name and optional default value from the matcher
    name = None
    default = None

    # Regex match object
    if hasattr(matcher, 'group'):
        try:
            name = matcher.group(1)
        except Exception:
            name = None
        try:
            default = matcher.group(2)
        except Exception:
            default = None
    # Tuple or list
    elif isinstance(matcher, (tuple, list)):
        if len(matcher) >= 1:
            name = matcher[0]
        if len(matcher) >= 2:
            default = matcher[1]
    # Dictionary
    elif isinstance(matcher, dict):
        name = matcher.get('name')
        default = matcher.get('default')
    else:
        # Try to treat matcher as a simple string
        name = str(matcher)

    if name is None:
        raise ValueError('Unable to resolve string: matcher does not contain a variable name')

    name = str(name)

    # Retrieve from environment
    value = os.environ.get(name)

    if value is not None:
        return value
    if default is not None:
        return default

    raise ValueError(f'Environment variable "{name}" not found and no default value provided')<|return|>

def get_pattern(pattern, strip=True):
