def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    import subprocess
    import os

    # Validate inputs
    if isinstance(commands, str):
        cmd_list = [commands]
    elif isinstance(commands, (list, tuple)):
        cmd_list = list(commands)
    else:
        raise TypeError("commands must be a string or a list/tuple of strings")

    if args is None:
        args = []
    if not isinstance(args, (list, tuple)):
        raise TypeError("args must be a list or tuple of strings")
    for a in args:
        if not isinstance(a, str):
            raise TypeError("each argument in args must be a string")

    # Prepare environment
    if env is not None:
        if not isinstance(env, dict):
            raise TypeError("env must be a dict or None")
        process_env = os.environ.copy()
        process_env.update(env)
    else:
        process_env = None  # subprocess will use the current environment

    completed = None
    for cmd in cmd_list:
        if not isinstance(cmd, str):
            raise TypeError("each command must be a string")
        # Build full command list: [cmd] + args
        full_cmd = [cmd] + list(args)

        if verbose:
            print(f"Running command: {' '.join(full_cmd)}")

        try:
            completed = subprocess.run(
                full_cmd,
                cwd=cwd,
                env=process_env,
                stdout=subprocess.PIPE,
                stderr=subprocess.DEVNULL if hide_stderr else subprocess.PIPE,
                text=True,
                check=True
            )
        except subprocess.CalledProcessError as exc:
            # If verbose, also print the stderr when not hidden
            if not hide_stderr and exc.stderr:
                print(f"Error output: {exc.stderr.strip()}", file=sys.stderr)
            raise

    # Return the CompletedProcess of the last command
    return completed<|return|>

