def _dump_string(obj, dumper=None):
    """Dump to a py2-unicode or py3-string"""
    # Use yaml to serialize the object to a YAML string.
    # If a specific Dumper is provided, use it; otherwise use safe_dump.
    if dumper:
        yaml_str = yaml.dump(obj, Dumper=dumper, allow_unicode=True, default_flow_style=False)
    else:
        yaml_str = yaml.safe_dump(obj, allow_unicode=True, default_flow_style=False)
    # Ensure the result is a unicode string on Python 2.
    try:
        # In Python 2, yaml_str will be a byte string; decode it to unicode.
        return yaml_str.decode('utf-8')
    except AttributeError:
        # In Python 3, yaml_str is already a str instance.
        return yaml_str<|return|>

