        except Exception as exc:
            errors.append(make_error(fname, fname, f"Could not read file {fname}: {exc}"))
            continue

        try:
            cfg = json.loads(content)
        except Exception as exc:
            errors.append(make_error(fname, fname, f"JSON decode error in {fname}: {exc}"))
            continue

        if not isinstance(cfg, dict):
            errors.append(make_error(fname, fname, f"Configuration file {fname} does not contain a JSON object (dict)"))
            continue

        if resolve_env:
            def expand(value):
                if isinstance(value, dict):
                    return {k: expand(v) for k, v in value.items()}
                if isinstance(value, list):
                    return [expand(v) for v in value]
                if isinstance(value, str):
                    return os.path.expandvars(value)
                return value
            cfg = expand(cfg)

        if overrides is not None:
            if not isinstance(overrides, dict):
                errors.append(make_error(fname, fname, f"Overrides provided for {fname} is not a dictionary"))
            else:
                for k, v in overrides.items():
                    if k in cfg:
                        cfg[k] = v

        configs[fname] = cfg

    return configs, errors<|return|>

