def verifyClass(iface, candidate, tentative=False):
    """Verify that the *candidate* might correctly provide *iface*."""
    # Validate the interface type
    if not isinstance(iface, type):
        raise TypeError("iface must be a class or interface type")

    # Determine if candidate is a class or an instance
    if isinstance(candidate, type):
        # Candidate is a class; use subclass check
        if issubclass(candidate, iface):
            return True
        candidate_cls = candidate
    else:
        # Candidate is an instance; use isinstance check
        if isinstance(candidate, iface):
            return True
        candidate_cls = type(candidate)

    # If not a subclass/instance, perform a tentative duck-typing verification
    if tentative:
        missing = []
        for attr in dir(iface):
            # Skip Python magic methods
            if attr.startswith("__") and attr.endswith("__"):
                continue
            if not hasattr(candidate_cls, attr):
                missing.append(attr)
        if missing:
            raise TypeError(
                f"Candidate {candidate_cls.__name__} does not provide all "
                f"required attributes for iface {iface.__name__}: "
                f"{', '.join(missing)}"
            )
        return True

    # If not tentative and the candidate doesn't subclass/implement the interface
    raise TypeError(f"Candidate {candidate if isinstance(candidate, type) else type(candidate).__name__} "
                    f"does not provide the interface {iface.__name__} and tentative verification is disabled.")<|return|>

def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__"""

    def _pick_super(a, b):
        """Return a simple super of two metaclasses or raise if conflict."""
        if a is None:
            return b
        if b is None:
            return a
        # a and b are types (metaclasses)
        try:
            if issubclass(a, b):
                return a
            if issubclass(b, a):
                return b
        except TypeError:
            # In case a or b is not a type
            pass
        raise TypeError(
            f"metaclass conflict: {getattr(a, '__name__', str(a))} is not a subclass of "
            f"{getattr(b, '__name__', str(b))} and vice versa"
        )

    # If an explicit metaclass is supplied, validate that it is compatible
    if explicit_mc is not None:
        if not isinstance(explicit_mc, type):
            raise TypeError(f"explicit __metaclass__ must be a type, got {type(explicit_mc).__name__}")
        for base in bases:
            meta = type(base)
            if not issubclass(explicit_mc, meta):
                raise TypeError(
                    f"explicit __metaclass__ {explicit_mc.__name__} is not a subclass of base metaclass "
                    f"{meta.__name__} for base {base.__name__}"
                )
        return explicit_mc

    # If there are no bases, the default metaclass is 'type'
    if not bases:
        return type

    # Determine the most derived metaclass implied by the bases
    # Start with the metaclass of the first base
    metaclass = type(bases[0])
    for base in bases[1:]:
        m = type(base)
        try:
            metaclass = _pick_super(metaclass, m)
        except TypeError as exc:
            # Preserve the original bases argument in the error message
            raise TypeError(
                f"metaclass conflict while processing bases {bases}: {exc}"
            ) from exc

    return metaclass
<|return|>

def pop(self, key, default=__marker):
    """
    D.pop(k[,d]) -> v, remove specified key and return the corresponding value.
    If key is not found, d is returned if given, otherwise KeyError is raised.
    """
    try:
        value = self[key]
    except KeyError:
        if default is __marker:
            raise
        return default
    del self[key]
    return value<|return|>

def popitem(self):
    """Remove and return the `(key, value)` pair least recently used."""
    try:
        key = next(iter(self))
    except StopIteration:
        raise KeyError('popitem(): dictionary is empty')
    value = self[key]
    del self[key]
    return key, value<|return|>

def popitem(self):
    """Remove and return the `(key, value)` pair most recently used."""
    try:
        # Python dicts (and OrderedDict) remove items in LIFO order by default,
        # which corresponds to the most recently used entry.
        return super().popitem()
    except KeyError as exc:
        # Mimic the built‑in behaviour: raise KeyError when the container is empty.
        raise KeyError("popitem(): dictionary is empty") from exc<|return|>

