def identify_request(request: RequestType):
    """Try to identify whether this is a Diaspora request.

    Try first public message. Then private message. The check if this is a legacy payload.
    """
    # Validate the input
    if not isinstance(request, RequestType):
        raise TypeError("request must be an instance of RequestType")

    # Utility to safely get a truthy attribute / callable result
    def _is_true(attr_name: str) -> bool:
        try:
            attr = getattr(request, attr_name, None)
            # If it's a callable (e.g., a method) call it
            if callable(attr):
                return bool(attr())
            # Otherwise treat it as a value
            return bool(attr)
        except Exception:
            # Any error reading the attribute is treated as False
            return False

    # 1. Public message
    if _is_true("is_public_message") or "public" in getattr(request, "type", "").lower():
        return True

    # 2. Private message
    if _is_true("is_private_message") or "private" in getattr(request, "type", "").lower():
        return True

    # 3. Legacy payload
    if _is_true("legacy") or getattr(request, "legacy_flag", False):
        return True

    # If none of the above matched, it's not a Diaspora request
    return False<|return|>

def identify_request(request: RequestType) -> bool:
    """
    Try to identify whether this is a Matrix request
    """
    # Matrix API requests typically contain the prefix '/_matrix/' in the URL path.
    # We perform duck-typing in case RequestType does not provide a specific interface.
    try:
        url = None
        # Common attribute names for the URL in request objects
        for attr in ("url", "path", "request_url", "request_path", "full_url"):
            try:
                url = getattr(request, attr)
                if isinstance(url, str):
                    break
            except Exception:
                continue

        if url is None:
            # If request is a dictionary or similar, attempt key access
            url = request.get("url") or request.get("path")

        if not isinstance(url, str):
            return False

        # Convert to lowercase to avoid case sensitivity issues
        url_lower = url.lower()

        # Simple heuristic: presence of '/_matrix/' indicates a Matrix request
        return "/_matrix/" in url_lower

    except Exception:
        # Any unexpected issue during inspection results in the conservative false
        return False<|return|>

def format_dt(dt):
    """
    Format a datetime in the way that D* nodes expect.
    """
    import datetime
    if dt is None:
        return ''
    # If it's a string that looks like a timestamp, return it unchanged
    if isinstance(dt, str):
        return dt
    # Handle numeric timestamps (seconds since epoch)
    if isinstance(dt, (int, float)):
        try:
            dt = datetime.datetime.fromtimestamp(dt)
        except Exception:
            return str(dt)
    # Handle date only objects
    if isinstance(dt, datetime.date) and not isinstance(dt, datetime.datetime):
        try:
            return dt.strftime('%Y-%m-%d')
        except Exception:
            return str(dt)
    # Ensure we have a datetime instance
    if not isinstance(dt, datetime.datetime):
        return str(dt)
    try:
        # If timezone naive, assume UTC
        if dt.tzinfo is None:
            return dt.replace(tzinfo=datetime.timezone.utc).isoformat(timespec='seconds')
        else:
            return dt.isoformat(timespec='seconds')
    except Exception:
        return str(dt)<|return|>

def test_tag(tag: str) -> bool:
    """Test a word whether it could be accepted as a tag."""
    try:
        if not isinstance(tag, str):
            raise TypeError("tag must be a string")
        if not tag:
            return False
        # Allowed characters: start with letter, followed by letters, digits, underscores or hyphens
        import re
        pattern = r'^[A-Za-z][A-Za-z0-9_-]*$'
        if not re.match(pattern, tag):
            return False
        return True
    except Exception:
        return False<|return|>

def xml_children_as_dict(node):
    """Turn the children of node <xml> into a dict, keyed by tag name.

    This is only a shallow conversation - child nodes are not recursively processed.
    """
    if node is None:
        return {}
    # Ensure node is iterable over its children
    try:
        children_iter = iter(node)
    except TypeError:
        # Not a valid XML element; return empty dict
        return {}
    result = {}
    for child in children_iter:
        # Only consider real element children that have a tag attribute
        tag = getattr(child, 'tag', None)
        if tag is None:
            continue
        if tag in result:
            existing = result[tag]
            if isinstance(existing, list):
                existing.append(child)
            else:
                result[tag] = [existing, child]
        else:
            result[tag] = child
    return result<|return|>

def get_nodeinfo_well_known_document(url, document_path=None):
    """Generate a NodeInfo .well-known document.

    See spec: http://nodeinfo.diaspora.software

    :arg url: The full base url with protocol, ie https://example.com
    :arg document_path: Custom NodeInfo document path if supplied (optional)
    :returns: dict
    """
    # Basic validation of the base URL
    if not isinstance(url, str) or not url:
        raise ValueError("url must be a non-empty string")

    # Normalize the base URL
    base = url.rstrip('/')

    # Normalise the document path: it should start with a slash and not end with one
    if document_path:
        if not isinstance(document_path, str):
            raise ValueError("document_path must be a string if provided")
        doc_path = document_path.strip()
        if not doc_path.startswith('/'):
            doc_path = '/' + doc_path
        doc_path = doc_path.rstrip('/')
    else:
        doc_path = '/nodeinfo'

    # The final NodeInfo endpoint is the base + doc_path + "/2.0"
    nodeinfo_endpoint = f"{base}{doc_path}/2.0"

    # Construct the well‑known document
    return {
        "links": [
            {
                "rel": "http://nodeinfo.diaspora.software/ns/schema/2.0",
                "href": nodeinfo_endpoint
            }
        ]
    }<|return|>

def verify_relayable_signature(public_key, doc, signature):
    """
    Verify the signed XML elements to have confidence that the claimed
    author did actually generate this message.
    Returns True if the signature is valid, False otherwise.
    """
    try:
        import xmlsec
        from lxml import etree
    except Exception:
        # Required libraries are missing
        return False

    # Prepare the XML document
    try:
        if isinstance(doc, str):
            doc_root = etree.fromstring(doc.encode('utf-8'))
        else:
            doc_root = doc
        if not isinstance(doc_root, etree._Element):
            return False
    except Exception:
        return False

    # Prepare the signature node
    try:
        if isinstance(signature, str):
            signature_node = etree.fromstring(signature.encode('utf-8'))
        else:
            signature_node = signature
        if not isinstance(signature_node, etree._Element):
            return False
    except Exception:
        return False

    try:
        # Create key from the provided PEM public key
        key = xmlsec.Key.from_memory(public_key.encode('utf-8'), xmlsec.KeyFormat.PEM, None)

        # Setup signature context
        ctx = xmlsec.SignatureContext()
        ctx.key = key

        # Register IDs to allow referencing within the document
        if hasattr(doc_root, "attrib") and "Id" in doc_root.attrib:
            ctx.register_id(doc_root, "Id")
        if hasattr(signature_node, "attrib") and "Id" in signature_node.attrib:
            ctx.register_id(signature_node, "Id")

        # Perform verification
        ctx.verify(signature_node)
        return True
    except Exception:
        # Any exception during verification results in a failed verification
        return False<|return|>

def parse_diaspora_webfinger(document: str) -> Dict:
    """Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    import json
    import xml.etree.ElementTree as ET

    # First try JSON
    try:
        data = json.loads(document)
        if not isinstance(data, dict):
            raise ValueError("JSON webfinger does not contain a JSON object")
        # Normalise keys to what you expect
        result: Dict = {}
        if "subject" in data:
            result["subject"] = data["subject"]
        if "properties" in data and isinstance(data["properties"], dict):
            result["properties"] = data["properties"]
        if "links" in data and isinstance(data["links"], list):
            result["links"] = data["links"]
        return result
    except json.JSONDecodeError:
        pass  # fall back to XRD

    # Try parsing XRD
    try:
        root = ET.fromstring(document)
    except ET.ParseError as e:
        raise ValueError("Failed to parse webfinger document as XML: %s" % e)

    def _strip_ns(tag):
        return tag.split("}")[-1] if "}" in tag else tag

    result: Dict = {"subject": None, "aliases": [], "links": []}

    for elem in root.iter():
        tag = _strip_ns(elem.tag)
        if tag == "Subject":
            result["subject"] = elem.text.strip() if elem.text else None
        elif tag == "Alias":
            if elem.text:
                result["aliases"].append(elem.text.strip())
        elif tag == "Link":
            href = elem.attrib.get("href")
            rel = elem.attrib.get("rel")
            type_attr = elem.attrib.get("type")
            link_entry = {}
            if href:
                link_entry["href"] = href
            if rel:
                link_entry["rel"] = rel
            if type_attr:
                link_entry["type"] = type_attr
            if link_entry:
                result["links"].append(link_entry)

    # Validate minimal presence of subject
    if not result["subject"]:
        raise ValueError("Webfinger document missing subject")

    return result
<|return|>

def try_retrieve_webfinger_document(handle: str) -> Optional[str]:
    """Try to retrieve an RFC7033 webfinger document. Does not raise if it fails."""
    # Normalize handle
    if handle.startswith('@'):
        handle = handle[1:]
    if '@' not in handle:
        return None

    # Build the resource parameter for the request
    resource = f"acct:{handle}"
    try:
        # urllib modules are assumed to be available in the environment
        from urllib import request, parse, error
    except Exception:
        # If urllib cannot be imported, we cannot proceed
        return None

    host = handle.split('@', 1)[1]
    url = f"https://{host}/.well-known/webfinger?resource={parse.quote(resource)}"

    try:
        with request.urlopen(url, timeout=5) as resp:
            # Acquire the response body; it could be bytes
            data = resp.read()
            # Attempt to decode as UTF-8; fall back to ISO-8859-1 if needed
            try:
                return data.decode('utf-8')
            except UnicodeDecodeError:
                return data.decode('iso-8859-1')
    except (error.URLError, error.HTTPError, ValueError, OSError):
        # Any failure (network, parsing, etc.) should result in None
        return None
    except Exception:
        # Catch-all for unexpected errors
        return None<|return|>

def retrieve_and_parse_diaspora_webfinger(handle):
    """
    Retrieve a and parse a remote Diaspora webfinger document.

    :arg handle: Remote handle to retrieve
    :returns: dict
    """
    # Validate input
    if not isinstance(handle, str):
        raise TypeError("handle must be a string")
    if "@" not in handle:
        raise ValueError("handle must be in the form 'user@domain'")

    # Extract domain part for the request URL
    _, domain = handle.split("@", 1)
    if not domain:
        raise ValueError("handle contains no domain part")

    # Construct the webfinger URL
    resource = f"acct:{handle}"
    url = f"https://{domain}/.well-known/webfinger?resource={resource}"

    try:
        import urllib.request
        import urllib.error
        import json

        req = urllib.request.Request(
            url,
            headers={
                "Accept": "application/jrd+json, application/json"
            },
            method="GET",
        )
        with urllib.request.urlopen(req, timeout=10) as resp:
            if resp.status != 200:
                raise RuntimeError(f"HTTP error {resp.status} when fetching {url}")
            data = resp.read().decode("utf-8")
            try:
                return json.loads(data)
            except json.JSONDecodeError as e:
                raise ValueError(f"Failed to parse JSON response from {url}: {e}") from e

    except urllib.error.HTTPError as e:
        raise RuntimeError(f"HTTP error fetching {url}: {e}") from e
    except urllib.error.URLError as e:
        raise RuntimeError(f"URL error fetching {url}: {e}") from e
    except Exception as e:
        raise RuntimeError(f"Unexpected error retrieving webfinger for {handle}: {e}") from e<|return|>

def retrieve_diaspora_host_meta(host):
    """Retrieve a remote Diaspora host-meta document.

    :arg host: Host to retrieve from
    :returns: ``XRD`` instance
    """
    if not host or not isinstance(host, str):
        raise TypeError("host must be a non-empty string")

    url = f"https://{host}/.well-known/host-meta"

    try:
        import urllib.request
        import urllib.error
        import ssl
    except Exception as exc:
        raise RuntimeError("Required standard library modules not available") from exc

    context = ssl.create_default_context()
    try:
        with urllib.request.urlopen(url, context=context, timeout=10) as resp:
            if resp.status != 200:
                raise RuntimeError(f"Failed to retrieve host-meta: HTTP {resp.status}")
            data = resp.read()
    except urllib.error.HTTPError as exc:
        raise RuntimeError(f"HTTP error retrieving host-meta from {host}: {exc}") from exc
    except urllib.error.URLError as exc:
        raise RuntimeError(f"URL error retrieving host-meta from {host}: {exc}") from exc
    except Exception as exc:
        raise RuntimeError(f"Unexpected error retrieving host-meta from {host}: {exc}") from exc

    try:
        return XRD(data.decode("utf-8"))
    except Exception as exc:
        raise RuntimeError(f"Failed to parse host-meta response as XRD: {exc}") from exc<|return|>

def list_of_file_names(settings_dirs, spec_option):
    """Create a new IniType complex type
    """
    from pathlib import Path
    import fnmatch

    result = []

    # Normalize settings_dirs to a list of paths
    if settings_dirs is None:
        return result

    if isinstance(settings_dirs, str):
        dirs = [settings_dirs]
    else:
        try:
            dirs = list(settings_dirs)
        except TypeError:
            raise TypeError("settings_dirs must be a string or an iterable of directory paths")

    # Determine the glob pattern to match file names
    if spec_option is None or (isinstance(spec_option, str) and spec_option == ""):
        pattern = "*"
    elif isinstance(spec_option, str):
        pattern = spec_option
    else:
        raise TypeError("spec_option must be a string glob pattern or None")

    for dir_path in dirs:
        try:
            p = Path(dir_path)
            if not p.is_dir():
                continue
            for item in p.iterdir():
                try:
                    if item.is_file() and fnmatch.fnmatch(item.name, pattern):
                        result.append(item.resolve().as_posix())
                except OSError:
                    # Skip items that cannot be accessed
                    continue
        except OSError:
            # Skip directories that cannot be accessed
            continue

    return sorted(result)<|return|>

