            f'Unsupported spec content type: {type(spec_content).__name__}')

    if not isinstance(data, dict):
        raise IRValidatorException(f'Spec content must be a mapping, got {type(data).__name__}')

    # Determine required fields; subclasses can override via class attribute
    required = getattr(cls, 'REQUIRED_FIELDS', [])
    for field in required:
        if field not in data:
            raise IRValidatorException(f'Missing required field: {field}')
        # Optionally check empty or null values
        if data[field] in (None, '', [], {}):
            raise IRValidatorException(f'Field "{field}" cannot be empty')

    return data<|return|>

@classmethod
    def validate_from_file(cls, yaml_file=None):
        """Loads & validates that a YAML file has all required fields

        :param yaml_file: Path to YAML file
        :raise IRValidatorException: when mandatory data is missing in file
        :return: Dictionary with data loaded from a YAML file
        """
        if yaml_file is None:
            raise ValueError("yaml_file must be provided")

        try:
            import yaml
            from pathlib import Path
            path = Path(yaml_file)
            if not path.is_file():
                raise FileNotFoundError(f"YAML file not found: {yaml_file}")
            with path.open("r", encoding="utf-8") as f:
                data = yaml.safe_load(f)
        except Exception as exc:  # pragma: no cover
            raise IRValidatorException(
                f"Error loading YAML file {yaml_file!r}: {exc}"
            ) from exc

        if not isinstance(data, dict):
            raise IRValidatorException(
                f"YAML file {yaml_file!r} must contain a top‑level mapping, but got {type(data).__name__}"
            )

        required = getattr(cls, "REQUIRED_FIELDS", None)
        if required:
            if not isinstance(required, (list, tuple)):
                raise TypeError(
                    f"Class attribute REQUIRED_FIELDS must be a list or tuple, got {type(required).__name__}"
                )
            missing = [field for field in required if field not in data]
            if missing:
                raise IRValidatorException(
                    f"Missing required fields in YAML file {yaml_file!r}: {', '.join(missing)}"
