def _include_groups(self, parser_dict):
    """Resolves the include dict directive in the spec files."""
    # Keep a set of already visited includes to avoid circular references
    visited = set()

    def _resolve(node):
        # Resolve includes inside dictionaries
        if isinstance(node, dict):
            # If the dict directly contains an include directive
            if 'include' in node:
                inc = node.pop('include')
                # Normalise to a list of names
                if isinstance(inc, str):
                    inc_names = [inc]
                else:
                    inc_names = list(inc)
                for name in inc_names:
                    if name in visited:
                        raise ValueError(f"Circular include detected for group '{name}'")
                    visited.add(name)
                    # Retrieve the group definition from the object's registry
                    group_def = getattr(self, '_groups', {}).get(name)
                    if group_def is None:
                        raise KeyError(f"Include group '{name}' not found")
                    # Recursively resolve nested includes in the group definition
                    _resolve(group_def)
                    # Merge the resolved group definition into the current dict
                    node.update(group_def)
            # Recurse into all values
            for key, value in list(node.items()):
                _resolve(value)
        elif isinstance(node, list):
            # Lists may contain nested dicts or other lists
            for item in node:
                _resolve(item)
        # Other types (int, str, etc.) are left untouched

    _resolve(parser_dict)<|return|>

def get_spec_defaults(self):
    """Resolve arguments' values from spec and other sources."""
    defaults = {}
    try:
        # Attempt to get the spec object or spec dict
        spec = getattr(self, "spec", None) or getattr(self, "_spec", None)

        if spec is None:
            # No spec available, nothing to resolve
            return defaults

        # If spec is a mapping (dict-like) containing argument specs
        if isinstance(spec, dict):
            for name, attr in spec.items():
                # attr might be a dict with a 'default' key
                if isinstance(attr, dict):
                    if "default" in attr:
                        defaults[name] = attr["default"]
                # attr might be an object with a default attribute or method
                else:
                    if hasattr(attr, "default") and not isinstance(attr.default, type):
                        defaults[name] = attr.default
                    elif hasattr(attr, "get_default") and callable(attr.get_default):
                        try:
                            defaults[name] = attr.get_default()
                        except Exception:
                            pass

        # If spec object has a get_default(name) method (possible in some libraries)
        elif hasattr(spec, "get_default") and callable(spec.get_default):
            for name in getattr(self, "_arg_names", []):
                try:
                    value = spec.get_default(name)
                    if value is not None:
                        defaults[name] = value
                except Exception:
                    pass

    except Exception:
        # If any unexpected error occurs, return what has been collected so far
        pass

    return defaults<|return|>

def get_deprecated_args(self):
