    # If the instance does not provide such a mapping, return an empty dict.
    # Any stored mapping must be a dict; otherwise raise a TypeError.
    deprecated = {}
    try:
        mapping = getattr(self, "_deprecated_args", None)
        if mapping is None:
            # No custom mapping provided; return empty dict.
            return {}
        if not isinstance(mapping, dict):
            raise TypeError(
                f"_deprecated_args attribute must be a dict, "
                f"got {type(mapping).__name__}"
