def validate_arg_deprecation(self, cli_args, answer_file_args):
    """Validates and prints the deprecated arguments.

    :param cli_args: the dict of arguments from cli
    :param answer_file_args:  the dict of arguments from files
    """
    # Basic type checking
    if not isinstance(cli_args, dict):
        raise TypeError(f"cli_args must be a dict, got {type(cli_args).__name__}")
    if not isinstance(answer_file_args, dict):
        raise TypeError(f"answer_file_args must be a dict, got {type(answer_file_args).__name__}")

    # Gather deprecated argument names if the class defines them
    deprecated = set()
    if hasattr(self, "deprecated_args"):
        try:
            deprecated = set(getattr(self, "deprecated_args"))
        except Exception:
            # ignore errors and treat as empty
            deprecated = set()

    # Check for duplicate definitions (CLI overrides answer file)
    for key in cli_args:
        if key in answer_file_args:
            # When the same arg is provided via both, we warn about overriding
            print(
                f"WARNING: Argument '{key}' provided via both CLI and answer file. "
                f"The CLI value will override the answer file value."
            )

    # Warn about deprecated arguments provided via CLI
    for key in cli_args:
        if key in deprecated:
            # If also provided via answer file, note that situation
            source = "both CLI and answer file" if key in answer_file_args else "CLI"
            print(f"DEPRECATION WARNING: Argument '{key}' is deprecated ({source}).")

    # Warn about deprecated arguments provided via answer file but not overridden
    for key in answer_file_args:
        if key in deprecated and key not in cli_args:
            print(f"DEPRECATION WARNING: Argument '{key}' is deprecated in answer file.")

    # No explicit return value needed
    return None<|return|>

