def validate_requires_args(self, args):
    """Check if all the required arguments have been provided."""
    # Ensure args is a mapping.  Allow None to mean "no arguments".
    if args is None:
        args = {}
    if not isinstance(args, dict):
        raise TypeError("args must be a dict or None")
    # Retrieve any declared required attributes.
    required = getattr(self, "REQUIRED_ATTRIBS", [])
    missing = []
    for key in required:
        if key not in args or args[key] is None:
            missing.append(key)
    if missing:
        # Build a clear error message.
        missing_str = ", ".join(f"'{k}'" for k in missing)
        raise ValueError(
            f"Missing required argument(s) {missing_str} for {self.__class__.__name__}"
        )
    return True<|return|>

def _get_conditionally_required_args(self, command_name, options_spec, args):
    """List arguments with ``required_when`` condition matched.

    :param command_name: the command name.
    :param options_spec:  the list of command spec options.
    :param args: the received input arguments
    :return: list, list of argument names with matched ``required_when`` condition
    """
    if args is None:
        args = {}
    required = []
    for opt in options_spec:
        # extract the option name
        if isinstance(opt, dict):
            name = opt.get("name")
            required_when = opt.get("required_when")
        else:
            name = getattr(opt, "name", None)
            required_when = getattr(opt, "required_when", None)

        if not name or required_when is None:
            continue

        try:
            if callable(required_when):
                if required_when(args):
                    required.append(name)
                continue
            if isinstance(required_when, bool):
                if required_when:
                    required.append(name)
                continue
            if isinstance(required_when, str):
                # Evaluate the condition string in a restricted namespace.
                # The expression may refer to keys in args.
                if eval(required_when, {}, args):
                    required.append(name)
                continue
        except Exception:  # pragma: no cover
            # If evaluating the condition fails, skip this option.
            continue

    return required<|return|>

def validate_length_args(self, args):
    """Check if value of arguments is not longer than length specified.

    :param args: The received arguments.
    """
    # Convert list/tuple of (key, value) pairs to a dictionary if needed
    if isinstance(args, (list, tuple)):
        try:
            args = dict(args)
        except Exception as e:
            raise TypeError(f"args must be a mapping or list/tuple of pairs, got {type(args).__name__}") from e

    if not isinstance(args, dict):
        raise TypeError(f"args must be a mapping, got {type(args).__name__}")

    # Optional mapping of argument names to maximum lengths (e.g., defined on the instance)
    max_lengths = getattr(self, 'ARG_MAX_LENGTHS', {})

    for key, value in args.items():
        # Skip checks if no maximum length is defined for this argument
        if key not in max_lengths:
            continue

        max_len = max_lengths[key]
        # Ensure that the limit is an integer or None (None meaning no limit)
        if max_len is None:
            continue
        if not isinstance(max_len, int) or max_len < 0:
            raise ValueError(f"Maximum length for '{key}' must be a non-negative integer, got {max_len!r}")

        # None values are exempt from length checks
        if value is None:
            continue

        # Try obtaining length; skip non-sized objects
        try:
            length = len(value)
        except Exception:
            continue  # non-collection types are silently ignored

        if length > max_len:
            raise ValueError(
                f"Argument '{key}' length {length} exceeds maximum allowed length of {max_len}"
            )<|return|>

def validate_choices_args(self, args):
    """Check if value of choice arguments is one of the available choices.

    :param args: The received arguments.
    """
    if not isinstance(args, dict):
        raise TypeError(f"'args' must be a dict, got {type(args).__name__}")

    # Retrieve the mapping of argument names to allowed values.
    # If the class doesn't define one, there's nothing to validate.
    choices = getattr(self, 'choices', {})
    if not choices:
        return

    for name, value in args.items():
        # Skip validation for arguments that are not defined as choice arguments.
        if name not in choices:
            continue

        allowed = choices[name]
        # Allow any iterable that supports membership testing. Convert to a set for performance.
        try:
            allowed_set = set(allowed)
        except TypeError:
            raise ValueError(f"Allowed values for argument '{name}' must be iterable")

        if value not in allowed_set:
            raise ValueError(
                f"Invalid value for argument '{name}': {value!r}. "
                f"Must be one of {sorted(allowed_set)!r}"
            )
    return True<|return|>

