def get_nested_custom_and_control_args(self, args):
        """Split input arguments to control nested and custom.

        Controls arguments: control the IR behavior. These arguments
            will not be put into the spec yml file
        Nested arguments: are used by the Ansible playbooks and will be put
            into the spec yml file.
        Custom arguments: Custom ansible variables to be used instead of the
            normal nested usage.

        :param args: the collected list of args.
        :return: (dict, dict): flat dicts (control_args, nested_args)
        """
        # Normalise the input to an iterable of key/value pairs.
        if args is None:
            return {}, {}

        # In many cases ``args`` is a dict; it might also be a list of
        # tuples or a list of dicts. Normalise all of these into a list of
        # (key, value) pairs.
        kv_pairs = []
        try:
            # Mapping type
            if hasattr(args, 'items'):
                for k, v in args.items():
                    kv_pairs.append((k, v))
            else:
                # Iterable of items
                for item in args:
                    if isinstance(item, dict):
                        for k, v in item.items():
                            kv_pairs.append((k, v))
                    elif isinstance(item, (list, tuple)) and len(item) == 2:
                        kv_pairs.append((item[0], item[1]))
                    else:
                        # We cannot interpret the item, safely ignore.
                        continue
        except Exception:
            # If anything goes wrong, return empty dicts
            return {}, {}

        control_args = {}
        nested_args = {}

        # Control & nested detection – but this is a best‑effort heuristic.
        # Any key that starts with '_' or 'control_' is considered a control
        # argument; all others are nested.  These prefixes are stripped from
        # the key in the output so that callers do not see the internal
        # convention markers.
        for key, value in kv_pairs:
            if not isinstance(key, str):
                continue
            # Remove a leading underscore or control_ prefix
            if key.startswith('_'):
                control_key = key.lstrip('_')
                control_args[control_key] = value
            elif key.startswith('control_'):
                control_key = key.replace('control_', '', 1)
                control_args[control_key] = value
            else:
                nested_args[key] = value

        return control_args, nested_args<|return|>

