    """Casts arguments to correct types by modifying values_dict param.

    By default all the values are strings.

    :param parser_name: The command name, e.g. main, virsh, ospd, etc
    :param values_dict: The dict of with arguments
    """
    # Retrieve a schema that defines the expected type for each argument.
    # The schema should be a dict mapping argument name to a type or
    # a tuple of (type, sub_type) for container types.
    # Example:
    #   {"port": int, "debug": bool, "tags": (list, str)}
    # The attribute ``parser_specs`` (or ``self.parser_specs``) is expected
    # to be set up elsewhere in the application. If it is not present,
    # or the parser_name is missing, we will use best‑effort guessing.
    schema = getattr(self, "parser_specs", {}).get(parser_name, {})

    def _convert_value(val, target_type):
        # Basic conversion for simple types
        if target_type is bool:
            if isinstance(val, str):
                return val.lower() in ("true", "1", "yes", "on")
            return bool(val)
        if target_type is int:
            try:
                return int(val)
            except Exception:
                pass
        if target_type is float:
            try:
                return float(val)
            except Exception:
                pass
        if target_type is str:
            return str(val)

        # Handle container types represented as tuples: (container, member_type)
        if isinstance(target_type, tuple) and len(target_type) == 2:
            container, member_type = target_type
            if isinstance(val, str):
                # Assume comma separated list or space separated for each item
                parts = [p.strip() for p in val.split(",") if p.strip()]
                if not parts:
                    parts = val.split()
            else:
                parts = val
            try:
                return container(_convert_value(p, member_type) for p in parts)
            except Exception:
                pass

        # If all conversions fail, return the original value
        return val

    for arg, raw_value in list(values_dict.items()):
        # Skip non-string values; they are considered already typed
        if not isinstance(raw_value, str):
            continue

        # Determine the target type
        target_type = schema.get(arg)

        # If type unknown, try simple heuristics
        if target_type is None:
            # Try bool
            if raw_value.lower() in ("true", "false", "1", "0", "yes", "no", "on", "off"):
                target_type = bool
            # Try int
            elif raw_value.isdigit() or (raw_value.startswith("-") and raw_value[1:].isdigit()):
                target_type = int
            else:
                # Try float
                try:
                    float(raw_value)
                    target_type = float
                except Exception:
                    target_type = str

        # Convert and update in place
        try:
            values_dict[arg] = _convert_value(raw_value, target_type)
