def get_plugin_spec_flatten_dict(plugin_dir):
    """Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    import os
    import json

    # Resolve plugin_dir to a string path
    plugin_dir = str(plugin_dir)
    plugin_dir = os.path.abspath(plugin_dir)

    # Look for the specification file; default to JSON
    spec_file = os.path.join(plugin_dir, "plugin_spec.json")
    if not os.path.isfile(spec_file):
        # If the exact file doesn't exist, give a clear error
        raise FileNotFoundError(
            f"Plugin specification file not found in '{plugin_dir}'. "
            f"Expected '{spec_file}'."
        )

    # Load the specification
    with open(spec_file, "r", encoding="utf-8") as f:
        try:
            spec = json.load(f)
        except json.JSONDecodeError as exc:
            raise ValueError(
                f"Failed to parse the plugin spec at '{spec_file}': {exc}"
            ) from exc

    # Helper to flatten nested dictionaries and lists
    def _flatten(node, parent_key="", sep=".", result=None):
        if result is None:
            result = {}
        if isinstance(node, dict):
            for k, v in node.items():
                new_key = f"{parent_key}{sep}{k}" if parent_key else k
                _flatten(v, new_key, sep, result)
        elif isinstance(node, list):
            for i, item in enumerate(node):
                new_key = f"{parent_key}{sep}{i}" if parent_key else str(i)
                _flatten(item, new_key, sep, result)
        else:
            result[parent_key] = node
        return result

    # Return the flattened dictionary
    return _flatten(spec)
