def extend_cli(self, root_subparsers):
    """Adds the spec cli options to to the main entry point.

    :param subparser: the subparser object to extend.
    """
    # Guard against a missing subparsers object
    if root_subparsers is None:
        return

    # Try to add a new subparser for this specific object
    try:
        # Use the class name as the command name, but allow subclasses to override it
        cmd_name = getattr(self, "cli_name", self.__class__.__name__.lower())
        description = getattr(self, "__doc__", "")
        subparser = root_subparsers.add_parser(cmd_name, help=description)
    except AttributeError:
        raise TypeError("root_subparsers must provide an add_parser() method")

    # If the object defines a helper to add its own arguments, call it
    add_args = getattr(self, "_add_cli_arguments", None)
    if callable(add_args):
        try:
