    # Normalize root: remove any trailing slash
    normalized_root = root.rstrip("/")
    # Ensure root is not empty
    if not normalized_root:
        raise ValueError("root must not be empty or '/'")

    # Ensure path starts with the normalized root
    if not path.startswith(normalized_root):
        raise ValueError(f"Path '{path}' does not start with root '{normalized_root}'")

    # Strip the root from the path
    stripped = path[len(normalized_root):]
    # Remove a leading slash if present
    if stripped.startswith("/"):
        stripped = stripped[1:]

    return stripped<|return|>
